// apps/web/src/components/auth/wallet-icons.tsx
"use client";

import React from "react";

const METAMASK_PNG = "data:image/png;base64,";
const COINBASE_PNG = "data:image/png;base64,";
const RABBY_PNG = "data:image/png;base64,";

interface WalletLogoProps {
  walletId: string;
  size?: number;
}

export function WalletLogo({ walletId, size = 30 }: WalletLogoProps) {
  if (walletId === "metamask") {
    return (
      <img
        src={METAMASK_PNG}
        alt="MetaMask"
        width={size}
        height={size}
        style={{
          width: size,
          height: size,
          borderRadius: 6,
          objectFit: "contain",
          display: "block",
        }}
      />
    );
  }

  if (walletId === "coinbase") {
    return (
      <img
        src={COINBASE_PNG}
        alt="Coinbase Wallet"
        width={size}
        height={size}
        style={{
          width: size,
          height: size,
          borderRadius: 6,
          objectFit: "contain",
          display: "block",
        }}
      />
    );
  }

  // Browser Wallet (Rabby/Brave)
  return (
    <img
      src={RABBY_PNG}
      alt="Browser Wallet"
      width={size}
      height={size}
      style={{
        width: size - 4,
        height: size - 4,
        objectFit: "contain",
        display: "block",
      }}
    />
  );
}
